"""Offline replay of real traces. It does not call a model or robot."""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
data = json.loads((ROOT / "results/suite.json").read_text())
html = r"""<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PrimeBuddy 本地技能调度 · 实验回放</title>
<style>*{box-sizing:border-box}body{margin:0;background:#f5f2ed;color:#27302d;font:16px/1.6 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}.shell{max-width:1420px;margin:auto;padding:28px 36px}header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #d9ddd5;padding-bottom:18px}.brand{font-size:22px;font-weight:750}.sub{font-size:12px;color:#69756d}.badge{background:#e0ebe3;color:#346b4c;padding:5px 13px;border-radius:30px;font-size:13px}.toolbar{display:flex;gap:10px;align-items:center;margin:22px 0}select,button{font:inherit;padding:8px 12px;border:1px solid #ccd4cd;border-radius:7px;background:white;cursor:pointer}button.active{background:#315e4d;color:white}.grid{display:grid;grid-template-columns:300px 1fr;gap:24px}.panel{background:#fff;border-radius:14px;border:1px solid #e1e4dd;padding:22px}.panel h2{font-size:16px;margin:0 0 16px}.skill{background:#f6f7f3;border-radius:9px;margin-top:10px;padding:13px}.skill b{color:#315e4d}.small{font-size:13px;color:#788478}.tag{display:inline-block;font-size:11px;border:1px solid #d3ddd5;border-radius:4px;padding:1px 6px;margin-top:5px}.bubble{background:#e7eee5;border-radius:12px 12px 2px 12px;padding:15px 20px;margin:5px 0 22px}.label{font-size:12px;letter-spacing:1px;color:#68816c;margin-bottom:5px}.cards{display:flex;gap:12px;align-items:stretch;margin:18px 0;flex-wrap:wrap}.task{border:1px solid #d5dfd6;border-radius:9px;padding:12px;min-width:150px;flex:1}.task.failed{border-color:#d29368;background:#fff6ee}.task.skipped{background:#f1f2f0;color:#808780}.task.running{border-color:#477e68}.task .id{font:12px monospace;color:#7e8a81}.task .status{font-size:12px;margin:7px 0;color:#39745b}.arrow{align-self:center;color:#97a69c}.reply{border-left:3px solid #4e8266;padding:12px 16px;background:#f6f8f3;margin-top:18px}.rows{margin-top:16px}.row{display:grid;grid-template-columns:64px 150px 1fr;gap:12px;border-bottom:1px solid #edf0ea;padding:8px 0;font-size:13px}.row time{color:#8a948b;font-family:monospace}.row b{font-weight:600}.empty{padding:25px;border:1px dashed #cbd8c8;border-radius:9px;color:#6d7e6b}.read{display:flex;gap:12px;margin:10px 0}.number{background:#e6ede3;border-radius:50%;width:28px;height:28px;text-align:center;flex-shrink:0}.code{white-space:pre-wrap;font:12px/1.65 ui-monospace,monospace;background:#f4f6f0;padding:14px;border-radius:8px;overflow:auto}.foot{margin:22px 0;font-size:12px;color:#879082}.headline{font-size:22px;margin:0 0 6px}details{font-size:13px;margin-top:12px}summary{cursor:pointer}.metric{display:flex;gap:10px;margin:20px 0}.metric div{flex:1;background:#f0f3ed;border-radius:9px;padding:12px}.metric strong{font-size:22px;display:block;color:#38634a}@media(max-width:800px){.grid{grid-template-columns:1fr}.shell{padding:15px}.cards{flex-direction:column}.row{grid-template-columns:50px 110px 1fr}}
</style><div class="shell"><header><div><div class="brand">PrimeBuddy / 本地技能调度</div><div class="sub">Qwen3-4B · RTX 5070 Ti · 原生技能注册与执行引擎</div></div><span class="badge">真实模型调用 / Mock 动作回放</span></header>
<div class="toolbar"><select id="cases"></select><button id="execution" class="active">执行过程</button><button id="reads">模型生成的计划</button></div>
<div class="grid"><aside class="panel"><h2>已注册的技能</h2><div class="skill"><b>greeting</b><div class="small">欢迎词、问候</div><span class="tag">speaker</span></div><div class="skill"><b>gesture</b><div class="small">挥手 wave / 比心 heart</div><span class="tag">robot.body</span></div><div class="skill"><b>dance</b><div class="small">跳舞 1–3 秒</div><span class="tag">robot.body</span></div><div class="metric" id="metric"></div><p class="small">模型提出计划；PrimeBuddy 校验参数、资源与依赖。执行回执由实际状态生成。</p></aside><main class="panel" id="main"></main></div><div class="foot">本页由保存的 trace.json 生成，可离线切换案例；不是实时控制台，不连接机器人。</div></div>
<script>const DATA=__DATA__;const names={wave:'换个说法：挥挥手',welcome:'完整迎宾：问候 → 挥手 → 跳舞',heart:'顺序任务：比心 → 跳舞',ambiguous:'含糊指令：来一个',unsupported:'未安装能力：倒水',failure:'执行失败：挥手失败后不跳舞',cancel:'取消任务：舞蹈中断，后续不执行'};const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let mode='execution';const sel=document.querySelector('#cases');for(const c of DATA.cases){let o=document.createElement('option');o.value=c.id;o.textContent=names[c.id]||c.id;sel.append(o)}
function render(){let c=DATA.cases.find(x=>x.id===sel.value);let tasks=c.batches.flatMap(b=>b.tasks.map(t=>({...t,result:b.results?.[t.id]})));document.querySelector('#metric').innerHTML='<div><strong>'+c.model_calls.length+'</strong><span class="small">模型调用</span></div><div><strong>'+c.backend_events.filter(x=>x.state==='start').length+'</strong><span class="small">启动动作</span></div>';let s='<div class="label">用户输入</div><div class="bubble">'+esc(c.text)+'</div>';
if(mode==='reads'){s+='<h2 class="headline">只生成已安装技能范围内的计划</h2><p class="small">下面是实际生成的 JSON；动作名和参数结构由技能定义约束。</p>';for(let i=0;i<c.model_calls.length;i++){let call=c.model_calls[i],t=call.parsed?.tool_calls?.[0];s+='<div class="read"><div class="number">'+(i+1)+'</div><div style="min-width:0;flex:1"><b>'+esc(t?.function?.name||(call.kind==='intent'?'意图判断':'动作计划 JSON'))+'</b><div class="code">'+esc(t?JSON.stringify(JSON.parse(t.function.arguments),null,2):(call.plan?JSON.stringify(call.plan,null,2):(call.parsed?.content||call.raw)))+'</div></div></div>'}}
else {s+='<h2 class="headline">'+(c.outcome==='cancelled'?'取消后，后续任务没有启动':tasks.length?'执行器只执行已通过校验的任务':'这句话没有启动任何动作')+'</h2>';if(tasks.length){s+='<div class="cards">';tasks.forEach((t,i)=>{let state=t.result?.status||(c.cancel_sent?(c.engine_events.some(e=>e.id===t.id&&e.state==='running')?'cancelled':'not_started'):'submitted');s+=(i?'<span class="arrow">→</span>':'')+'<div class="task '+state+'"><div class="id">'+esc(t.id)+'</div><b>'+esc(t.skill+'.'+t.action)+'</b><div class="status">'+esc(state)+'</div><div class="small">'+esc(JSON.stringify(t.args))+'</div><div class="small">after: '+esc(t.after.join(', ')||'无')+'</div></div>'});s+='</div>'}else s+='<div class="empty">tasks 为空 / 没有 Mock 动作启动</div>';if(c.final)s+='<div class="label">'+(c.outcome==='cancelled'?'程序的取消回执':(tasks.length?'执行回执（程序生成）':'模型追问 / 能力说明'))+'</div><div class="reply">'+esc(c.final)+'</div>';if(c.error)s+='<p class="small">'+esc(c.error.type+': '+c.error.message)+'</p>';s+='<div class="rows"><h2>Mock 动作日志</h2>';const ev=c.backend_events,base=ev[0]?.t||0;for(let e of ev){s+='<div class="row"><time>+'+(e.t-base).toFixed(2)+'s</time><b>'+esc(e.action)+'</b><span>'+esc(e.state)+(e.reason?' · '+esc(e.reason):'')+'</span></div>'}if(!ev.length)s+='<p class="small">空：没有动作副作用。</p>';s+='</div>';}s+='<details><summary>查看原始结构化记录</summary><pre class="code">'+esc(JSON.stringify({batches:c.batches,engine_events:c.engine_events},null,2))+'</pre></details>';document.querySelector('#main').innerHTML=s;document.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.id===mode));}
sel.onchange=render;document.querySelectorAll('button').forEach(b=>b.onclick=()=>{mode=b.id;render()});const params=new URLSearchParams(location.search);if(params.has('case'))sel.value=params.get('case');if(params.has('mode'))mode=params.get('mode');render();window.replayReady=true;</script></html>"""
(ROOT / "运行回放.html").write_text(
    html.replace("__DATA__", json.dumps(data, ensure_ascii=False).replace("</", "<\\/"))
)
print("viewer ready")
